package minimercado.modelo;
import java.time.LocalDate; import java.util.*;
/** Venta a un cliente. Compone los detalles y el pago; solo descuenta stock si el pago es aprobado. */
public class Factura { private int idFactura; private String numero; private LocalDate fecha=LocalDate.now(); private double subtotal,iva,total; private boolean estado; private Cliente cliente; private Empleado empleado; private final ArrayList<DetalleFactura> detalles=new ArrayList<>(); private Pago pago; public Factura(int id,String numero,Cliente c,Empleado e,Pago p){idFactura=id;this.numero=numero;cliente=c;empleado=e;pago=p;} public void agregarDetalle(DetalleFactura d){detalles.add(d);calcularTotal();} public double calcularTotal(){subtotal=detalles.stream().mapToDouble(DetalleFactura::getSubtotal).sum();iva=subtotal*0.19;return total=subtotal+iva;} public boolean generarFactura(){if(pago==null||!pago.procesarPago())return false;for(DetalleFactura d:detalles)d.getProducto().actualizarStock(-d.getCantidad());estado=true;return true;} public String getNumero(){return numero;} public LocalDate getFecha(){return fecha;} public double getSubtotal(){return subtotal;} public double getIva(){return iva;} public double getTotal(){return total;} public boolean isEstado(){return estado;} public Cliente getCliente(){return cliente;} public Pago getPago(){return pago;} }
